function safeJsonParseMaybe(v) {

  if (typeof v !== "string") return v;
  const s = v.trim();
  if (!s) return v;
  if (!(s.startsWith("{") || s.startsWith("["))) return v;
  try { return JSON.parse(s); } catch { return v; }
}

const input = $input.first()?.json ?? {};

// 2) Normalize in case anything is a JSON string
const normalized = safeJsonParseMaybe(input) || {};
const run_id = normalized.run_id ?? input.run_id ?? null;
const results = safeJsonParseMaybe(normalized.results ?? input.results) ?? [];
const unmatched_doers = safeJsonParseMaybe(normalized.unmatched_doers ?? input.unmatched_doers) ?? [];


return [
  {
    json: {
      run_id,
      results,
      unmatched_doers,
    },
  },
];
